        'sh_free_step3_desc' => 'ਐਡਮਿਨ ਨੂੰ ਨਵੀਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬਾਰੇ ਸੂਚਨਾ ਈਮੇਲ ਮਿਲਦੀ ਹੈ। ਵਰਤੋਂਕਾਰ ਨੂੰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਪ੍ਰਾਪਤ ਹੋਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ "ਸਮੀਖਿਆ ਅਧੀਨ" ਈਮੇਲ ਮਿਲਦੀ ਹੈ।',
        'sh_free_step4_title' => 'ਵਰਤੋਂਕਾਰ "ਸਮੀਖਿਆ ਅਧੀਨ" ਪੰਨਾ ਦੇਖਦਾ ਹੈ',
        'sh_free_step4_desc' => 'ਵਰਤੋਂਕਾਰ ਨੂੰ ਇੱਕ ਵੱਖਰੇ ਪੰਨੇ ਤੇ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ ਜੋ ਦੱਸਦਾ ਹੈ ਕਿ ਉਨ੍ਹਾਂ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੀ ਸਮੀਖਿਆ ਹੋ ਰਹੀ ਹੈ ਅਤੇ ਮਨਜ਼ੂਰ ਹੋਣ ਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਈਮੇਲ ਮਿਲੇਗੀ।',
        'sh_free_step5_title' => 'ਐਡਮਿਨ ਹੋਸਟਿੰਗ ਪੈਨਲ ਵਿੱਚ ਸਬਡੋਮੇਨ ਬਣਾਉਂਦਾ ਹੈ',
        'sh_free_step5_desc' => 'ਐਡਮਿਨ cPanel / Plesk / ਹੋਸਟਿੰਗ ਪੈਨਲ ਵਿੱਚ ਲੌਗਇਨ ਕਰਦਾ ਹੈ ਅਤੇ ਐਪਲੀਕੇਸ਼ਨ ਡਾਇਰੈਕਟਰੀ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਸਬਡੋਮੇਨ (ਜਿਵੇਂ <code>company.yourdomain.com</code>) ਹੱਥੀਂ ਬਣਾਉਂਦਾ ਹੈ। ਇਹ ਲੋੜੀਂਦਾ ਹੈ ਕਿਉਂਕਿ ਸਾਂਝੀ ਹੋਸਟਿੰਗ ਵਾਈਲਡਕਾਰਡ DNS ਨੂੰ ਸਮਰਥਨ ਨਹੀਂ ਦਿੰਦੀ।',
        'sh_free_step6_title' => 'ਐਡਮਿਨ ਡਾਟਾਬੇਸ ਬਣਾਉਂਦਾ ਹੈ ਅਤੇ ਪ੍ਰਮਾਣ-ਪੱਤਰ ਕੌਂਫਿਗਰ ਕਰਦਾ ਹੈ',
        'sh_free_step6_desc' => 'ਐਡਮਿਨ ਹੋਸਟਿੰਗ ਪੈਨਲ ਵਿੱਚ ਨਵਾਂ MySQL ਡਾਟਾਬੇਸ ਅਤੇ ਵਰਤੋਂਕਾਰ ਬਣਾਉਂਦਾ ਹੈ (cPanel > MySQL Databases), ਫਿਰ <a href=":tenants_url">ਟੈਨੈਂਟ</a> ਜਾਂ <a href=":dashboard_url">ਡੈਸ਼ਬੋਰਡ</a> ਤੇ ਜਾਂਦਾ ਹੈ, <strong>"ਕੌਂਫਿਗਰ ਕਰੋ ਅਤੇ ਮਨਜ਼ੂਰ ਕਰੋ"</strong> ਤੇ ਕਲਿੱਕ ਕਰਦਾ ਹੈ ਅਤੇ ਡਾਟਾਬੇਸ ਪ੍ਰਮਾਣ-ਪੱਤਰ (ਹੋਸਟ, ਨਾਮ, ਵਰਤੋਂਕਾਰ, ਪਾਸਵਰਡ, ਪੋਰਟ) ਭਰਦਾ ਹੈ।',
        'sh_free_step7_title' => 'ਕਨੈਕਸ਼ਨ ਦੀ ਜਾਂਚ ਅਤੇ ਪ੍ਰੋਵਿਜ਼ਨਿੰਗ',
        'sh_free_step7_desc' => 'ਸਿਸਟਮ DB ਕਨੈਕਸ਼ਨ ਦੀ ਜਾਂਚ ਕਰਦਾ ਹੈ, ਮਾਈਗ੍ਰੇਸ਼ਨ ਚਲਾਉਂਦਾ ਹੈ, ਡਾਟਾ ਸੀਡ ਕਰਦਾ ਹੈ, ਐਡਮਿਨ ਵਰਤੋਂਕਾਰ ਬਣਾਉਂਦਾ ਹੈ ਅਤੇ Passport ਇੰਸਟਾਲ ਕਰਦਾ ਹੈ। ਜੇ ਕੋਈ ਕਦਮ ਅਸਫਲ ਹੋਵੇ, ਤਾਂ ਐਡਮਿਨ ਨੂੰ ਸਪਸ਼ਟ ਗਲਤੀ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ ਅਤੇ ਟੈਨੈਂਟ ਬਕਾਇਆ ਰਹਿੰਦਾ ਹੈ।',
        'sh_free_step8_title' => 'ਟੈਨੈਂਟ ਸਰਗਰਮ ਅਤੇ ਈਮੇਲ ਭੇਜੀ ਗਈ',
        'sh_free_step8_desc' => 'ਸਥਿਤੀ <code>active</code> ਵਿੱਚ ਬਦਲ ਜਾਂਦੀ ਹੈ। ਵਰਤੋਂਕਾਰ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਵਰਕਸਪੇਸ URL ਅਤੇ ਲੌਗਇਨ ਲਿੰਕ ਨਾਲ ਮਨਜ਼ੂਰੀ ਈਮੇਲ ਮਿਲਦੀ ਹੈ।',
        'sh_paid_step1_title' => 'ਵਰਤੋਂਕਾਰ ਰਜਿਸਟਰ ਕਰਦਾ ਹੈ ਅਤੇ ਭੁਗਤਾਨ ਕਰਦਾ ਹੈ',
        'sh_paid_step1_desc' => 'ਵਰਤੋਂਕਾਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫਾਰਮ ਭਰਦਾ ਹੈ, ਭੁਗਤਾਨ ਵਾਲਾ ਪਲਾਨ ਚੁਣਦਾ ਹੈ ਅਤੇ ਕੌਂਫਿਗਰ ਕੀਤੇ ਭੁਗਤਾਨ ਗੇਟਵੇ ਰਾਹੀਂ ਚੈੱਕਆਊਟ ਪੂਰਾ ਕਰਦਾ ਹੈ।',
        'sh_paid_step2_title' => 'ਭੁਗਤਾਨ ਦੀ ਪੁਸ਼ਟੀ ਹੋਈ',
        'sh_paid_step2_desc' => 'ਭੁਗਤਾਨ ਗੇਟਵੇ ਭੁਗਤਾਨ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ। ਬਿਲਿੰਗ ਭੁਗਤਾਨ ਰਿਕਾਰਡ ਸੁਰੱਖਿਅਤ ਹੁੰਦਾ ਹੈ। <strong>ਹਾਲੇ ਕੋਈ ਡਾਟਾਬੇਸ ਜਾਂ ਪ੍ਰੋਵਿਜ਼ਨਿੰਗ ਨਹੀਂ ਹੁੰਦੀ।</strong>',
        'sh_paid_step3_title' => 'ਟੈਨੈਂਟ "ਬਕਾਇਆ" ਵਜੋਂ ਬਣਾਇਆ ਗਿਆ',
        'sh_paid_step3_desc' => 'ਟੈਨੈਂਟ ਰਿਕਾਰਡ <code>pending</code> ਸਥਿਤੀ ਨਾਲ ਬਣਦਾ ਹੈ। ਸਬਸਕ੍ਰਿਪਸ਼ਨ <code>pending</code> ਸੈੱਟ ਹੁੰਦੀ ਹੈ। ਐਡਮਿਨ ਅਤੇ ਵਰਤੋਂਕਾਰ ਨੂੰ ਈਮੇਲਾਂ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
        'sh_paid_step4_title' => 'ਵਰਤੋਂਕਾਰ ਨੂੰ "ਸਮੀਖਿਆ ਅਧੀਨ" ਪੰਨੇ ਤੇ ਭੇਜਿਆ ਗਿਆ',
        'sh_paid_step4_desc' => 'ਵਰਤੋਂਕਾਰ ਨੂੰ ਇੱਕ ਪੰਨਾ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ ਜੋ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ ਕਿ ਭੁਗਤਾਨ ਪ੍ਰਾਪਤ ਹੋ ਗਿਆ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦਾ ਵਰਕਸਪੇਸ ਐਡਮਿਨ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਵਿੱਚ ਹੈ।',
        'sh_paid_step5_title' => 'ਐਡਮਿਨ ਸਬਡੋਮੇਨ ਅਤੇ ਡਾਟਾਬੇਸ ਬਣਾਉਂਦਾ ਹੈ',
        'sh_paid_step5_desc' => 'ਐਡਮਿਨ ਹੋਸਟਿੰਗ ਪੈਨਲ (cPanel, Plesk, ਆਦਿ) ਵਿੱਚ ਹੱਥੀਂ ਸਬਡੋਮੇਨ ਅਤੇ ਨਵਾਂ MySQL ਡਾਟਾਬੇਸ ਬਣਾਉਂਦਾ ਹੈ।',
        'sh_paid_step6_title' => 'ਐਡਮਿਨ ਕੌਂਫਿਗਰ ਕਰਦਾ ਅਤੇ ਮਨਜ਼ੂਰ ਕਰਦਾ ਹੈ',
        'sh_paid_step6_desc' => 'ਐਡਮਿਨ ਮਨਜ਼ੂਰੀ ਫਾਰਮ ਵਿੱਚ DB ਪ੍ਰਮਾਣ-ਪੱਤਰ ਦਾਖਲ ਕਰਦਾ ਹੈ, ਕਨੈਕਸ਼ਨ ਦੀ ਜਾਂਚ ਕਰਦਾ ਹੈ ਅਤੇ ਮਨਜ਼ੂਰ ਕਰਦਾ ਹੈ। ਸਿਸਟਮ ਮਾਈਗ੍ਰੇਸ਼ਨ ਚਲਾਉਂਦਾ ਹੈ ਅਤੇ ਵਰਕਸਪੇਸ ਪ੍ਰੋਵਿਜ਼ਨ ਕਰਦਾ ਹੈ।',
        'sh_paid_step7_title' => 'ਟੈਨੈਂਟ ਸਰਗਰਮ ਹੋਇਆ',
        'sh_paid_step7_desc' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸਰਗਰਮ ਹੋਈ, ਮਨਜ਼ੂਰੀ ਈਮੇਲ ਭੇਜੀ ਗਈ, ਵਰਕਸਪੇਸ ਵਰਤੋਂਕਾਰ ਲਈ ਤਿਆਰ ਹੈ।',
        'shared_note_label' => 'ਮਹੱਤਵਪੂਰਨ:',
        'shared_note' => 'ਸਾਂਝੀ ਹੋਸਟਿੰਗ ਮੋਡ ਵਿੱਚ, ਮਨਜ਼ੂਰ ਕਰਨ ਤੋਂ <em>ਪਹਿਲਾਂ</em> ਤੁਹਾਨੂੰ ਸਬਡੋਮੇਨ <strong>ਅਤੇ</strong> ਡਾਟਾਬੇਸ ਦੋਵੇਂ (cPanel, Plesk, ਆਦਿ ਰਾਹੀਂ) ਹੱਥੀਂ ਬਣਾਉਣੇ ਪੈਣਗੇ। ਸਿਸਟਮ ਡਾਟਾਬੇਸ ਨਾਲ ਕਨੈਕਟ ਕਰੇਗਾ ਅਤੇ ਟ੍ਰੈਫਿਕ ਨੂੰ ਸਬਡੋਮੇਨ ਤੇ ਭੇਜੇਗਾ, ਪਰ ਸਾਂਝੀ ਹੋਸਟਿੰਗ ਤੇ ਇਨ੍ਹਾਂ ਨੂੰ ਆਪਣੇ-ਆਪ ਨਹੀਂ ਬਣਾ ਸਕਦਾ।',
        'db_security_title' => 'ਡਾਟਾਬੇਸ ਸੁਰੱਖਿਆ',
        'db_sec_encrypt_title' => 'AES-256 ਇਨਕ੍ਰਿਪਟ ਕੀਤੇ ਪਾਸਵਰਡ',
        'db_sec_encrypt_desc' => 'ਡਾਟਾਬੇਸ ਪਾਸਵਰਡ ਸਟੋਰ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ AES-256-CBC (Laravel ਦੀ APP_KEY ਰਾਹੀਂ) ਨਾਲ ਇਨਕ੍ਰਿਪਟ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਅਸਲ ਪਾਸਵਰਡ ਕਦੇ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ।',
        'db_sec_isolate_title' => 'ਅਲੱਗ ਟੈਨੈਂਟ ਡਾਟਾਬੇਸ',
        'db_sec_isolate_desc' => 'ਹਰ ਟੈਨੈਂਟ ਦਾ ਆਪਣਾ ਡਾਟਾਬੇਸ ਹੁੰਦਾ ਹੈ। ਜਦੋਂ ਟੈਨੈਂਟ ਲੌਗਇਨ ਕਰਦਾ ਹੈ, ਸਿਸਟਮ ਉਨ੍ਹਾਂ ਦੇ ਇਨਕ੍ਰਿਪਟ ਕੀਤੇ ਪ੍ਰਮਾਣ-ਪੱਤਰ ਲੋਡ ਕਰਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਅਲੱਗ ਡਾਟਾਬੇਸ ਨਾਲ ਕਨੈਕਟ ਕਰਦਾ ਹੈ।',
        'db_sec_test_title' => 'ਕਨੈਕਸ਼ਨ ਟੈਸਟ ਕਰੋ',
        'db_sec_test_desc' => 'ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਟੈਨੈਂਟ ਵੇਰਵੇ ਪੰਨੇ ਤੋਂ "ਕਨੈਕਸ਼ਨ ਟੈਸਟ ਕਰੋ" ਬਟਨ ਨਾਲ ਡਾਟਾਬੇਸ ਪ੍ਰਮਾਣ-ਪੱਤਰਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰ ਸਕਦੇ ਹੋ।',
        'db_sec_migrate_title' => 'ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੁਬਾਰਾ ਚਲਾਓ',
        'db_sec_migrate_desc' => 'ਜੇ ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੁਬਾਰਾ ਲਾਗੂ ਕਰਨ ਦੀ ਲੋੜ ਹੋਵੇ (ਜਿਵੇਂ ਅੱਪਡੇਟ ਤੋਂ ਬਾਅਦ), ਤਾਂ ਟੈਨੈਂਟ ਵੇਰਵੇ ਪੰਨੇ ਤੇ "ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੁਬਾਰਾ ਚਲਾਓ" ਬਟਨ ਵਰਤੋ।',
        'lifecycle_title' => 'ਟੈਨੈਂਟ ਸਥਿਤੀ ਜੀਵਨ-ਚੱਕਰ',
        'status_pending' => 'ਬਕਾਇਆ',
        'status_provisioning' => 'ਪ੍ਰੋਵਿਜ਼ਨਿੰਗ',
        'status_active' => 'ਸਰਗਰਮ',
        'status_suspended' => 'ਮੁਅੱਤਲ',
        'status_cancelled' => 'ਰੱਦ ਕੀਤੀ',
        'status_failed' => 'ਅਸਫਲ',
        'status_pending_desc' => 'ਐਡਮਿਨ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਵਿੱਚ। ਸਿਰਫ਼ ਸਾਂਝੀ ਹੋਸਟਿੰਗ ਮੋਡ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।',
        'status_provisioning_desc' => 'ਡਾਟਾਬੇਸ ਸੈੱਟਅੱਪ ਹੋ ਰਿਹਾ ਹੈ, ਮਾਈਗ੍ਰੇਸ਼ਨ ਚੱਲ ਰਹੀਆਂ ਹਨ, ਐਡਮਿਨ ਵਰਤੋਂਕਾਰ ਬਣ ਰਿਹਾ ਹੈ।',
        'status_active_desc' => 'ਪੂਰੀ ਤਰ੍ਹਾਂ ਪ੍ਰੋਵਿਜ਼ਨ ਅਤੇ ਪਹੁੰਚਯੋਗ। ਟੈਨੈਂਟ ਲੌਗਇਨ ਕਰ ਸਕਦਾ ਹੈ ਅਤੇ ਵਰਕਸਪੇਸ ਵਰਤ ਸਕਦਾ ਹੈ।',
        'status_suspended_desc' => 'ਐਡਮਿਨ ਵੱਲੋਂ ਅਸਥਾਈ ਤੌਰ ਤੇ ਬੰਦ। ਟੈਨੈਂਟ ਆਪਣੇ ਵਰਕਸਪੇਸ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚ ਸਕਦਾ।',
        'status_cancelled_desc' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰੱਦ ਕੀਤੀ ਗਈ। ਵਰਕਸਪੇਸ ਹਾਲੇ ਮੌਜੂਦ ਹੋ ਸਕਦਾ ਹੈ ਪਰ ਪਹੁੰਚ ਸੀਮਤ ਹੈ।',
        'status_failed_desc' => 'ਗਲਤੀ ਕਾਰਨ ਪ੍ਰੋਵਿਜ਼ਨਿੰਗ ਅਸਫਲ ਰਹੀ। ਐਡਮਿਨ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦਾ ਹੈ ਜਾਂ ਗਲਤੀ ਵੇਰਵੇ ਦੇਖ ਸਕਦਾ ਹੈ।',
        'faq_title' => 'ਅਕਸਰ ਪੁੱਛੇ ਜਾਂਦੇ ਸਵਾਲ',
        'faq_subtitle' => 'ਪਲਾਨ, ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ, ਬਿਲਿੰਗ ਅਤੇ ਟੈਨੈਂਟ ਪ੍ਰਬੰਧਨ ਬਾਰੇ ਆਮ ਸਵਾਲ।',
        'faq_q1' => 'ਜੇ ਮੈਂ ਕਿਸੇ ਪਲਾਨ ਦੇ ਫੀਚਰ ਬਦਲਾਂ, ਤਾਂ ਕੀ ਇਹ ਸਾਰੇ ਸਬਸਕ੍ਰਾਈਬਰਾਂ ਲਈ ਆਪਣੇ-ਆਪ ਅੱਪਡੇਟ ਹੋ ਜਾਵੇਗਾ?',
        'faq_a1' => '<strong>ਹਾਂ, ਤੁਰੰਤ।</strong> ਫੀਚਰ ਅਤੇ ਸੀਮਾਵਾਂ ਲਾਈਵ ਪਲਾਨ ਦੇ ਵਿਰੁੱਧ ਰੀਅਲ-ਟਾਈਮ ਵਿੱਚ ਜਾਂਚੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਸਿਸਟਮ ਫੀਚਰਾਂ ਦਾ ਸਨੈਪਸ਼ਾਟ ਸਟੋਰ ਨਹੀਂ ਕਰਦਾ — ਜਦੋਂ ਵੀ ਟੈਨੈਂਟ ਕੋਈ ਕਾਰਵਾਈ ਕਰਦਾ ਹੈ (ਜਿਵੇਂ ਉਤਪਾਦ ਬਣਾਉਣਾ), ਮਿਡਲਵੇਅਰ ਪਹੁੰਚ ਦੀ ਪੁਸ਼ਟੀ ਲਈ ਮੌਜੂਦਾ ਪਲਾਨ ਨੂੰ ਕਵੇਰੀ ਕਰਦਾ ਹੈ। ਇਸ ਲਈ ਜੇ ਤੁਸੀਂ ਪਲਾਨ ਵਿੱਚ ਫੀਚਰ ਜੋੜਦੇ ਜਾਂ ਹਟਾਉਂਦੇ ਹੋ, ਤਾਂ ਉਸ ਪਲਾਨ ਦੇ ਸਾਰੇ ਸਬਸਕ੍ਰਾਈਬਰ ਆਪਣੀ ਅਗਲੀ ਬੇਨਤੀ ਤੇ ਹੀ ਤਬਦੀਲੀ ਦੇਖਣਗੇ।',
        'faq_q2' => 'ਜੇ ਮੈਂ ਕਿਸੇ ਪਲਾਨ ਦੀ ਕੀਮਤ ਵਧਾਵਾਂ, ਤਾਂ ਕੀ ਮੌਜੂਦਾ ਸਬਸਕ੍ਰਾਈਬਰਾਂ ਤੋਂ ਨਵੀਂ ਕੀਮਤ ਵਸੂਲੀ ਜਾਵੇਗੀ?',
        'faq_a2' => '<strong>ਨਹੀਂ।</strong> ਜਦੋਂ ਟੈਨੈਂਟ ਸਬਸਕ੍ਰਾਈਬ ਕਰਦਾ ਹੈ, ਉਸ ਸਮੇਂ ਦੀ ਕੀਮਤ ਉਨ੍ਹਾਂ ਦੇ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰਿਕਾਰਡ ਵਿੱਚ ਲਾਕ ਹੋ ਜਾਂਦੀ ਹੈ। ਪਲਾਨ ਦੀ ਕੀਮਤ ਬਦਲਣ ਦਾ ਅਸਰ ਸਿਰਫ਼ <strong>ਨਵੀਆਂ</strong> ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ ਅਤੇ <strong>ਭਵਿੱਖ ਦੇ ਨਵੀਨੀਕਰਨ ਜਾਂ ਪਲਾਨ ਤਬਦੀਲੀਆਂ</strong> ਤੇ ਪੈਂਦਾ ਹੈ। ਮੌਜੂਦਾ ਸਰਗਰਮ ਸਬਸਕ੍ਰਾਈਬਰ ਨਵੀਨੀਕਰਨ ਜਾਂ ਪਲਾਨ ਬਦਲਣ ਤੱਕ ਉਹੀ ਰਕਮ ਅਦਾ ਕਰਦੇ ਰਹਿੰਦੇ ਹਨ ਜਿਸ ਲਈ ਉਹ ਸਹਿਮਤ ਹੋਏ ਸਨ।',
        'faq_q3' => 'ਜੇ ਮੈਂ ਕੋਈ ਪਲਾਨ ਮਿਟਾਵਾਂ, ਤਾਂ ਕੀ ਮੌਜੂਦਾ ਸਬਸਕ੍ਰਾਈਬਰ ਅਜੇ ਵੀ ਆਪਣਾ ਖਾਤਾ ਵਰਤ ਸਕਦੇ ਹਨ?',
        'faq_a3' => '<strong>ਤੁਸੀਂ ਸਰਗਰਮ ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ ਵਾਲਾ ਪਲਾਨ ਨਹੀਂ ਮਿਟਾ ਸਕਦੇ।</strong> ਸਿਸਟਮ ਮਿਟਾਉਣ ਤੋਂ ਰੋਕਦਾ ਹੈ ਅਤੇ ਗਲਤੀ ਦਿਖਾਉਂਦਾ ਹੈ। ਇਹ ਐਪਲੀਕੇਸ਼ਨ ਪੱਧਰ ਅਤੇ ਡਾਟਾਬੇਸ ਪੱਧਰ (ਫੋਰਨ ਕੀ ਪਾਬੰਦੀ) ਦੋਵਾਂ ਤੇ ਲਾਗੂ ਹੈ। ਪਲਾਨ ਹਟਾਉਣ ਲਈ, ਪਹਿਲਾਂ ਉਸ ਦੇ ਸਾਰੇ ਸਬਸਕ੍ਰਾਈਬਰਾਂ ਨੂੰ ਕਿਸੇ ਹੋਰ ਪਲਾਨ ਵਿੱਚ ਭੇਜੋ, ਜਾਂ ਸਾਰੀਆਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ ਖਤਮ ਹੋਣ ਤੱਕ ਉਡੀਕ ਕਰੋ।',
        'faq_a3_tip' => 'ਮਿਟਾਉਣ ਦੀ ਬਜਾਏ, ਪਲਾਨ ਨੂੰ <strong>ਨਿੱਜੀ</strong> ਚਿੰਨ੍ਹਿਤ ਕਰੋ — ਇਹ ਲੈਂਡਿੰਗ ਪੇਜ ਤੋਂ ਲੁਕ ਜਾਵੇਗਾ ਪਰ ਮੌਜੂਦਾ ਸਬਸਕ੍ਰਾਈਬਰਾਂ ਦੀ ਪਹੁੰਚ ਬਣੀ ਰਹੇਗੀ।',
        'faq_q4' => 'ਕੀ ਟੈਨੈਂਟ ਆਪਣੇ ਪਲਾਨ ਨੂੰ ਅੱਪਗ੍ਰੇਡ ਜਾਂ ਡਾਊਨਗ੍ਰੇਡ ਕਰ ਸਕਦੇ ਹਨ?',
        'faq_a4_p1' => '<strong>ਹਾਂ।</strong> ਟੈਨੈਂਟ ਕਿਸੇ ਵੀ ਸਮੇਂ ਆਪਣੇ ਬਿਲਿੰਗ ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਆਪਣਾ ਪਲਾਨ ਬਦਲ ਸਕਦੇ ਹਨ। ਜਦੋਂ ਉਹ ਨਵਾਂ ਪਲਾਨ ਚੁਣਦੇ ਹਨ, ਤਾਂ ਨਵੇਂ ਪਲਾਨ ਦੀ ਕੀਮਤ ਲਈ ਨਵਾਂ ਭੁਗਤਾਨ ਲੋੜੀਂਦਾ ਹੈ। ਮੌਜੂਦਾ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਨਵੇਂ ਪਲਾਨ, ਬਿਲਿੰਗ ਚੱਕਰ ਅਤੇ ਰਕਮ ਨਾਲ ਉਸੇ ਥਾਂ ਅੱਪਡੇਟ ਹੋ ਜਾਂਦੀ ਹੈ। ਨਵੀਂ ਬਿਲਿੰਗ ਮਿਆਦ ਭੁਗਤਾਨ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।',
        'faq_a4_p2' => 'ਐਡਮਿਨ ਵਜੋਂ, ਤੁਸੀਂ ਸੁਪਰ ਐਡਮਿਨ ਪੈਨਲ ਦੇ <strong>ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ</strong> ਭਾਗ ਤੋਂ ਵੀ ਟੈਨੈਂਟ ਦੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਹੱਥੀਂ ਬਦਲ ਸਕਦੇ ਹੋ।',
        'faq_q5' => 'ਫੀਚਰ ਸੀਮਾਵਾਂ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀਆਂ ਹਨ? (ਜਿਵੇਂ ਵੱਧ ਤੋਂ ਵੱਧ ਉਤਪਾਦ, ਵੱਧ ਤੋਂ ਵੱਧ ਵਰਤੋਂਕਾਰ)',
        'faq_a5_intro' => 'ਹਰੇਕ ਪਲਾਨ ਉਤਪਾਦਾਂ, ਵਰਤੋਂਕਾਰਾਂ, ਗੋਦਾਮਾਂ, ਗਾਹਕਾਂ ਅਤੇ ਸਪਲਾਇਰਾਂ ਦੀ ਵੱਧ ਤੋਂ ਵੱਧ ਗਿਣਤੀ ਵਰਗੀਆਂ ਸੀਮਾਵਾਂ ਤੈਅ ਕਰ ਸਕਦਾ ਹੈ। ਇਹ ਸੀਮਾਵਾਂ ਰੀਅਲ-ਟਾਈਮ ਵਿੱਚ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ:',
        'faq_a5_li1' => 'ਜਦੋਂ ਟੈਨੈਂਟ ਨਵਾਂ ਰਿਕਾਰਡ <strong>ਬਣਾਉਣ</strong> ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹੈ, ਸਿਸਟਮ ਗਿਣਦਾ ਹੈ ਕਿ ਉਨ੍ਹਾਂ ਕੋਲ ਪਹਿਲਾਂ ਕਿੰਨੇ ਹਨ ਅਤੇ ਇਸ ਦੀ ਪਲਾਨ ਸੀਮਾ ਨਾਲ ਤੁਲਨਾ ਕਰਦਾ ਹੈ।',
        'faq_a5_li2' => 'ਜੇ ਸੀਮਾ ਪੂਰੀ ਹੋ ਜਾਵੇ, ਤਾਂ ਸੁਨੇਹੇ ਨਾਲ ਰਿਕਾਰਡ ਬਣਾਉਣਾ ਰੋਕ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।',
        'faq_a5_li3' => 'ਮੌਜੂਦਾ ਰਿਕਾਰਡ <strong>ਕਦੇ ਨਹੀਂ ਮਿਟਾਏ ਜਾਂਦੇ</strong> — ਜੇ ਤੁਸੀਂ ਸੀਮਾ ਘਟਾਉਂਦੇ ਹੋ, ਤਾਂ ਟੈਨੈਂਟ ਆਪਣਾ ਡਾਟਾ ਰੱਖਦੇ ਹਨ ਪਰ ਸੀਮਾ ਦੇ ਹੇਠਾਂ ਆਉਣ ਤੱਕ ਹੋਰ ਨਹੀਂ ਜੋੜ ਸਕਦੇ।',
        'faq_a5_li4' => '<code>-1</code> ਦੀ ਸੀਮਾ ਮੁੱਲ ਦਾ ਮਤਲਬ ਹੈ <strong>ਅਸੀਮਿਤ</strong>।',
        'faq_q6' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਦੀ ਮਿਆਦ ਪੁੱਗਣ ਤੇ ਕੀ ਹੁੰਦਾ ਹੈ?',
        'faq_a6_intro' => 'ਸਿਸਟਮ ਰੋਜ਼ਾਨਾ ਇੱਕ ਆਟੋਮੈਟਿਕ ਜਾਂਚ ਚਲਾਉਂਦਾ ਹੈ:',
        'faq_a6_li1' => '<strong>ਮਿਆਦ ਪੁੱਗਣ ਤੋਂ 7 ਦਿਨ ਪਹਿਲਾਂ:</strong> ਟੈਨੈਂਟ ਨੂੰ ਨਵਿਆਉਣ ਦੀ ਯਾਦ ਦਿਵਾਉਂਦੀ ਚੇਤਾਵਨੀ ਈਮੇਲ ਭੇਜੀ ਜਾਂਦੀ ਹੈ।',
        'faq_a6_li2' => '<strong>ਮਿਆਦ ਪੁੱਗਣ ਦੀ ਮਿਤੀ ਤੇ:</strong> ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸਥਿਤੀ <code>expired</code> ਵਿੱਚ ਬਦਲ ਜਾਂਦੀ ਹੈ ਅਤੇ ਸੂਚਨਾ ਈਮੇਲ ਭੇਜੀ ਜਾਂਦੀ ਹੈ।',
        'faq_a6_li3' => '<strong>ਮਿਆਦ ਪੁੱਗਣ ਤੋਂ ਬਾਅਦ:</strong> ਟੈਨੈਂਟ ਹਾਲੇ ਵੀ ਆਪਣਾ ਡਾਟਾ ਦੇਖ ਸਕਦਾ ਹੈ ਪਰ ਫੀਚਰਾਂ ਤੱਕ ਪਹੁੰਚ ਤੁਹਾਡੀ ਕੌਂਫਿਗਰੇਸ਼ਨ ਅਨੁਸਾਰ ਸੀਮਤ ਹੋ ਜਾਂਦੀ ਹੈ।',
        'faq_a6_outro' => 'ਟੈਨੈਂਟ ਕਿਸੇ ਵੀ ਸਮੇਂ ਆਪਣੇ ਬਿਲਿੰਗ ਪੰਨੇ ਤੋਂ ਨਵਾਂ ਭੁਗਤਾਨ ਕਰਕੇ ਨਵਿਆ ਸਕਦਾ ਹੈ।',
        'faq_q7' => 'ਜਦੋਂ ਮੈਂ ਕਿਸੇ ਟੈਨੈਂਟ ਨੂੰ ਮੁਅੱਤਲ ਕਰਦਾ ਹਾਂ ਤਾਂ ਕੀ ਹੁੰਦਾ ਹੈ?',
        'faq_a7_p1' => '<strong>ਸਾਰੀ ਪਹੁੰਚ ਤੁਰੰਤ ਬਲਾਕ ਹੋ ਜਾਂਦੀ ਹੈ।</strong> ਜਦੋਂ ਟੈਨੈਂਟ ਦੀ ਸਥਿਤੀ <code>suspended</code> ਜਾਂ <code>cancelled</code> ਸੈੱਟ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਵਰਕਸਪੇਸ ਦੀ ਹਰ ਬੇਨਤੀ <strong>403 Forbidden</strong> ਗਲਤੀ ਦਿੰਦੀ ਹੈ। ਉਹ ਲੌਗਇਨ ਨਹੀਂ ਕਰ ਸਕਦੇ, API ਨਹੀਂ ਵਰਤ ਸਕਦੇ ਜਾਂ ਐਪਲੀਕੇਸ਼ਨ ਦੇ ਕਿਸੇ ਵੀ ਹਿੱਸੇ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚ ਸਕਦੇ।',
        'faq_a7_p2' => 'ਉਨ੍ਹਾਂ ਦਾ ਡਾਟਾ ਅਤੇ ਡਾਟਾਬੇਸ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦੇ ਹਨ। ਟੈਨੈਂਟ ਨੂੰ ਦੁਬਾਰਾ ਸਰਗਰਮ ਕਰਨ ਨਾਲ ਪੂਰੀ ਪਹੁੰਚ ਤੁਰੰਤ ਬਹਾਲ ਹੋ ਜਾਂਦੀ ਹੈ।',
        'faq_q8' => 'ਅਜ਼ਮਾਇਸ਼ ਮਿਆਦ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ?',
        'faq_a8_intro' => 'ਜਦੋਂ ਕਿਸੇ ਪਲਾਨ ਵਿੱਚ ਅਜ਼ਮਾਇਸ਼ ਚਾਲੂ ਹੋਵੇ:',
        'faq_a8_li1' => 'ਸਾਈਨਅੱਪ ਤੇ <strong>ਕਿਸੇ ਭੁਗਤਾਨ ਦੀ ਲੋੜ ਨਹੀਂ</strong> — ਟੈਨੈਂਟ ਨੂੰ ਅਜ਼ਮਾਇਸ਼ ਦੌਰਾਨ ਪਲਾਨ ਦੇ ਫੀਚਰਾਂ ਤੱਕ ਪੂਰੀ ਪਹੁੰਚ ਮਿਲਦੀ ਹੈ।',
        'faq_a8_li2' => 'ਅਜ਼ਮਾਇਸ਼ ਦੀ ਮਿਆਦ ਹਰੇਕ ਪਲਾਨ ਲਈ ਕੌਂਫਿਗਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ (ਜਿਵੇਂ 7 ਦਿਨ, 14 ਦਿਨ) ਜਾਂ ਗਲੋਬਲ ਡਿਫਾਲਟ ਤੇ ਵਾਪਸ ਆ ਜਾਂਦੀ ਹੈ।',
        'faq_a8_li3' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਤੇ <code>trial_ends_at</code> ਮਿਤੀ ਸੈੱਟ ਹੁੰਦੀ ਹੈ। ਜਦੋਂ ਤੱਕ ਇਹ ਮਿਤੀ ਭਵਿੱਖ ਵਿੱਚ ਹੈ, ਟੈਨੈਂਟ ਕੋਲ ਪੂਰੀ ਪਹੁੰਚ ਰਹਿੰਦੀ ਹੈ।',
        'faq_a8_li4' => 'ਜਦੋਂ ਅਜ਼ਮਾਇਸ਼ ਖਤਮ ਹੁੰਦੀ ਹੈ, ਵਰਕਸਪੇਸ ਵਰਤਣਾ ਜਾਰੀ ਰੱਖਣ ਲਈ ਟੈਨੈਂਟ ਨੂੰ ਪਲਾਨ ਖਰੀਦਣਾ ਪੈਂਦਾ ਹੈ।',
        'faq_q9' => 'ਜਦੋਂ ਟੈਨੈਂਟ ਆਪਣੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰੱਦ ਕਰਦਾ ਹੈ ਤਾਂ ਕੀ ਹੁੰਦਾ ਹੈ?',
        'faq_a9_intro' => 'ਜਦੋਂ ਟੈਨੈਂਟ ਰੱਦ ਕਰਦਾ ਹੈ:',
        'faq_a9_li1' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸਥਿਤੀ <code>cancelled</code> ਵਿੱਚ ਬਦਲ ਜਾਂਦੀ ਹੈ, ਪਰ ਟੈਨੈਂਟ <strong>ਆਪਣੀ ਮੌਜੂਦਾ ਬਿਲਿੰਗ ਮਿਆਦ ਦੇ ਅੰਤ ਤੱਕ ਪਹੁੰਚ ਰੱਖਦਾ ਹੈ</strong> (<code>ends_at</code> ਮਿਤੀ)।',
        'faq_a9_li2' => 'ਬਿਲਿੰਗ ਮਿਆਦ ਖਤਮ ਹੋਣ ਤੇ, ਸਥਿਤੀ <code>expired</code> ਵਿੱਚ ਚਲੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਪਹੁੰਚ ਸੀਮਤ ਹੋ ਜਾਂਦੀ ਹੈ।',
        'faq_a9_li3' => 'ਟੈਨੈਂਟ ਬਿਲਿੰਗ ਮਿਆਦ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਆਪਣੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ <strong>ਮੁੜ ਸ਼ੁਰੂ</strong> ਕਰ ਸਕਦਾ ਹੈ, ਜੋ ਇਸਨੂੰ <code>active</code> ਤੇ ਬਹਾਲ ਕਰ ਦਿੰਦਾ ਹੈ।',
        'faq_q10' => 'ਗੈਰ-ਸਰਗਰਮ ਜਾਂ ਛੱਡੇ ਗਏ ਟੈਨੈਂਟ ਖਾਤਿਆਂ ਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ?',
        'faq_a10_intro' => 'ਸਿਸਟਮ ਵਿੱਚ ਇੱਕ ਆਟੋਮੈਟਿਕ ਸਫ਼ਾਈ ਪ੍ਰਕਿਰਿਆ ਹੈ ਜੋ ਰੋਜ਼ਾਨਾ ਚੱਲਦੀ ਹੈ:',
        'faq_a10_li1' => '<strong>ਮੁਅੱਤਲੀ:</strong> ਮਿਆਦ ਪੁੱਗੀਆਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ ਵਾਲੇ ਟੈਨੈਂਟ ਜੋ 7 ਦਿਨਾਂ ਤੋਂ ਵੱਧ ਗੈਰ-ਸਰਗਰਮ ਰਹੇ ਹਨ, ਆਪਣੇ-ਆਪ ਮੁਅੱਤਲ ਕਰ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ।',
        'faq_a10_li2' => '<strong>ਮਿਟਾਉਣਾ:</strong> ਮੁਅੱਤਲ/ਰੱਦ/ਅਸਫਲ ਟੈਨੈਂਟ ਜੋ 90 ਦਿਨਾਂ ਤੋਂ ਵੱਧ ਗੈਰ-ਸਰਗਰਮ ਰਹੇ ਹਨ, ਆਪਣੇ-ਆਪ ਮਿਟਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ (ਡਾਟਾਬੇਸ, ਡੋਮੇਨ, ਸਬਸਕ੍ਰਿਪਸ਼ਨਾਂ ਅਤੇ ਭੁਗਤਾਨ ਰਿਕਾਰਡ ਹਟਾਏ ਜਾਂਦੇ ਹਨ)।',
        'faq_a10_li3' => 'ਗਤੀਵਿਧੀ <code>last_activity_at</code> ਖੇਤਰ ਰਾਹੀਂ ਟਰੈਕ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਜੋ ਹਰ ਵਾਰ ਟੈਨੈਂਟ ਦੇ ਵਰਕਸਪੇਸ ਤੱਕ ਪਹੁੰਚਣ ਤੇ ਅੱਪਡੇਟ ਹੁੰਦਾ ਹੈ।',
        'faq_a10_outro' => 'ਤੁਸੀਂ <strong>ਡੈਸ਼ਬੋਰਡ</strong> ਦੇ ਸਿਹਤ ਅਲਰਟ ਭਾਗ ਤੋਂ ਗੈਰ-ਸਰਗਰਮ ਟੈਨੈਂਟਾਂ ਦੀ ਨਿਗਰਾਨੀ ਕਰ ਸਕਦੇ ਹੋ।',
        'faq_q11' => 'ਜੇ ਮੈਂ ਕਿਸੇ ਪਲਾਨ ਦੀ ਸੀਮਾ ਘਟਾਵਾਂ, ਤਾਂ ਕੀ ਮੌਜੂਦਾ ਡਾਟਾ ਮਿਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ?',
        'faq_a11' => '<strong>ਨਹੀਂ, ਮੌਜੂਦਾ ਡਾਟਾ ਕਦੇ ਨਹੀਂ ਮਿਟਾਇਆ ਜਾਂਦਾ।</strong> ਜੇ ਤੁਸੀਂ ਪਲਾਨ ਦੀ ਉਤਪਾਦ ਸੀਮਾ 500 ਤੋਂ ਘਟਾ ਕੇ 100 ਕਰਦੇ ਹੋ, ਤਾਂ ਜਿਨ੍ਹਾਂ ਟੈਨੈਂਟਾਂ ਕੋਲ ਪਹਿਲਾਂ ਹੀ 300 ਉਤਪਾਦ ਹਨ ਉਹ ਸਾਰੇ 300 ਰੱਖਣਗੇ। ਹਾਲਾਂਕਿ, ਨਵੀਂ ਸੀਮਾ ਤੋਂ ਹੇਠਾਂ ਆਉਣ ਤੱਕ (ਜਿਵੇਂ ਕੁਝ ਮਿਟਾ ਕੇ) ਉਹ ਨਵੇਂ ਉਤਪਾਦ ਨਹੀਂ ਬਣਾ ਸਕਣਗੇ। ਸੀਮਾ ਸਿਰਫ਼ <strong>ਬਣਾਉਣ</strong> ਨੂੰ ਸੀਮਤ ਕਰਦੀ ਹੈ, ਮੌਜੂਦਾ ਰਿਕਾਰਡਾਂ ਨੂੰ ਨਹੀਂ।',
        'faq_q12' => 'ਕੀ ਹਰੇਕ ਟੈਨੈਂਟ ਦਾ ਡਾਟਾ ਦੂਜੇ ਟੈਨੈਂਟਾਂ ਤੋਂ ਅਲੱਗ ਹੈ?',
        'faq_a12' => '<strong>ਹਾਂ, ਪੂਰੀ ਤਰ੍ਹਾਂ।</strong> ਹਰੇਕ ਟੈਨੈਂਟ ਦਾ ਆਪਣਾ ਸਮਰਪਿਤ ਡਾਟਾਬੇਸ ਹੁੰਦਾ ਹੈ। ਜਦੋਂ ਟੈਨੈਂਟ ਲੌਗਇਨ ਕਰਦਾ ਹੈ, ਸਿਸਟਮ ਇਨਕ੍ਰਿਪਟ ਕੀਤੇ ਪ੍ਰਮਾਣ-ਪੱਤਰਾਂ ਨਾਲ ਉਨ੍ਹਾਂ ਦੇ ਖਾਸ ਡਾਟਾਬੇਸ ਨਾਲ ਕਨੈਕਟ ਕਰਦਾ ਹੈ। ਟੈਨੈਂਟਾਂ ਵਿਚਕਾਰ ਕੋਈ ਸਾਂਝਾ ਡਾਟਾ ਨਹੀਂ ਹੈ — ਇੱਕ ਟੈਨੈਂਟ ਕਦੇ ਵੀ ਦੂਜੇ ਟੈਨੈਂਟ ਦੇ ਉਤਪਾਦ, ਗਾਹਕ, ਵਿਕਰੀ ਜਾਂ ਕੋਈ ਹੋਰ ਡਾਟਾ ਨਹੀਂ ਦੇਖ ਸਕਦਾ।',
        'faq_q13' => 'ਕੀ ਮੈਂ ਇੱਕੋ ਪਲਾਨ ਲਈ ਮਹੀਨਾਵਾਰ ਅਤੇ ਸਾਲਾਨਾ ਦੋਵੇਂ ਬਿਲਿੰਗ ਪੇਸ਼ ਕਰ ਸਕਦਾ ਹਾਂ?',
        'faq_a13' => '<strong>ਹਾਂ।</strong> ਹਰੇਕ ਪਲਾਨ ਮਹੀਨਾਵਾਰ ਕੀਮਤ ਅਤੇ ਸਾਲਾਨਾ ਕੀਮਤ ਦੋਵਾਂ ਨੂੰ ਸਮਰਥਨ ਦਿੰਦਾ ਹੈ। ਪਲਾਨ ਬਣਾਉਣ ਜਾਂ ਸੋਧਣ ਸਮੇਂ ਤੁਸੀਂ ਦੋਵੇਂ ਕੀਮਤਾਂ ਸੈੱਟ ਕਰਦੇ ਹੋ। ਟੈਨੈਂਟ ਚੈੱਕਆਊਟ ਦੌਰਾਨ ਆਪਣਾ ਪਸੰਦੀਦਾ ਬਿਲਿੰਗ ਚੱਕਰ ਚੁਣਦੇ ਹਨ। ਸਾਲਾਨਾ ਕੀਮਤ ਆਮ ਤੌਰ ਤੇ 12 ਮਹੀਨਿਆਂ ਦੀ ਮਹੀਨਾਵਾਰ ਕੀਮਤ ਦੇ ਮੁਕਾਬਲੇ ਛੋਟ ਦਿੰਦੀ ਹੈ, ਅਤੇ ਬੱਚਤ ਪ੍ਰਤੀਸ਼ਤ ਕੀਮਤ ਪੰਨੇ ਤੇ ਆਪਣੇ-ਆਪ ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ।',
        'faq_q14' => 'ਕੀ ਮੈਂ ਕਿਸੇ ਪਲਾਨ ਨੂੰ ਮਿਟਾਏ ਬਿਨਾਂ ਲੈਂਡਿੰਗ ਪੇਜ ਤੋਂ ਲੁਕਾ ਸਕਦਾ ਹਾਂ?',
        'faq_a14' => '<strong>ਹਾਂ।</strong> ਪਲਾਨ ਬਣਾਉਣ ਜਾਂ ਸੋਧਣ ਸਮੇਂ ਉਸਨੂੰ <strong>ਨਿੱਜੀ</strong> ਚਿੰਨ੍ਹਿਤ ਕਰੋ। ਨਿੱਜੀ ਪਲਾਨ ਜਨਤਕ ਕੀਮਤ ਪੰਨੇ ਤੋਂ ਲੁਕੇ ਰਹਿੰਦੇ ਹਨ ਪਰ ਮੌਜੂਦਾ ਸਬਸਕ੍ਰਾਈਬਰਾਂ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕੰਮ ਕਰਦੇ ਰਹਿੰਦੇ ਹਨ। ਇਹ ਪੁਰਾਣੇ ਪਲਾਨਾਂ, ਕਸਟਮ ਐਂਟਰਪ੍ਰਾਈਜ਼ ਸੌਦਿਆਂ ਜਾਂ ਉਨ੍ਹਾਂ ਪਲਾਨਾਂ ਲਈ ਉਪਯੋਗੀ ਹੈ ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ ਬੰਦ ਕਰ ਰਹੇ ਹੋ।',
        'faq_q15' => 'ਕਿਹੜੇ ਭੁਗਤਾਨ ਗੇਟਵੇ ਸਮਰਥਿਤ ਹਨ?',
        'faq_a15' => 'ਪਲੇਟਫਾਰਮ ਕਈ ਭੁਗਤਾਨ ਗੇਟਵੇ ਨੂੰ ਸਮਰਥਨ ਦਿੰਦਾ ਹੈ ਜੋ <strong>ਸੈਟਿੰਗਾਂ > ਭੁਗਤਾਨ ਗੇਟਵੇ</strong> ਤੋਂ ਕੌਂਫਿਗਰ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ। ਹਰੇਕ ਗੇਟਵੇ ਸੁਰੱਖਿਆ ਲਈ ਵੈੱਬਹੁੱਕ ਰਾਹੀਂ ਭੁਗਤਾਨ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ — ਟੈਨੈਂਟ ਪ੍ਰੋਵਿਜ਼ਨ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਭੁਗਤਾਨ ਦੀ ਸਰਵਰ-ਸਾਈਡ ਪੁਸ਼ਟੀ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਤੁਸੀਂ ਲੋੜ ਅਨੁਸਾਰ ਗੇਟਵੇ ਚਾਲੂ ਜਾਂ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ।',
        'quick_actions' => 'ਤੇਜ਼ ਕਾਰਵਾਈਆਂ',
